def decode_z(z, mean, std, enabled: bool, beta: float = 0.1):
    """Constrain physical rainfall, including per-row client scales in central pools."""
    if not enabled:
        return z
    rainfall = nn.functional.softplus(mean.to(torch.float64) + std.to(torch.float64)*z.to(torch.float64), beta=beta)
    return (rainfall-mean)/std
